import React, { useState, useEffect, useRef } from 'react';
import { gsap } from 'gsap';
import partListData from './part_list.json';
import PixiCanvas from './components/PixiCanvas';
import lottie from 'lottie-web';

function App() {
  // Form state
  const [selectedLine, setSelectedLine] = useState('');
  const [selectedPart, setSelectedPart] = useState('');
  const [production, setProduction] = useState('');
  const [availableParts, setAvailableParts] = useState([]);

  // UI state
  const [showSubmitButton, setShowSubmitButton] = useState(false);
  const [currentStep, setCurrentStep] = useState(0); // 0 = form, 1-4 = sections
  // Removed sectionAnimating as it's not used in the current implementation
  const [showRestartButton, setShowRestartButton] = useState(false);

  // Animated values for Section 4
  const [animatedWage, setAnimatedWage] = useState(0);
  const [animatedSteel, setAnimatedSteel] = useState(0);
  const [animatedOverhead, setAnimatedOverhead] = useState(0);
  const [animatedMargin, setAnimatedMargin] = useState(0);

  // Frame scrub state (Section 1 & 2)
  const [currentFrame1, setCurrentFrame1] = useState(0);
  const [currentFrame2, setCurrentFrame2] = useState(0);
  const [frames1Loaded, setFrames1Loaded] = useState(false);
  const [frames2Loaded, setFrames2Loaded] = useState(false);

  // Refs for sections
  const section1Ref = useRef(null);
  const section2Ref = useRef(null);
  const section3Ref = useRef(null);
  const section4Ref = useRef(null);

  // Data helpers
  const lines = [...new Set(partListData.map(item => item.Line))].sort();
  const selectedPartData = availableParts.find(p => p.SKU.toString() === selectedPart);

  // ---- Window resize handler ----
  useEffect(() => {
    const handleResize = () => {
      // Trigger re-render for responsive components
      window.dispatchEvent(new Event('resize'));
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // ---- Build available parts when line changes ----
  useEffect(() => {
    if (!selectedLine) {
      setAvailableParts([]);
      setSelectedPart('');
      return;
    }
    const parts = partListData
      .filter(item => item.Line === selectedLine)
      .map(item => ({
        SKU: item.SKU,
        'Carton Qty': item['Carton Qty'],
        'Unit Weight (lb)': item['Unit Weight (lb)'],
        'Price (ea)': item['Price (ea)']
      }));
    setAvailableParts(parts);
    setSelectedPart('');
  }, [selectedLine]);

  // ---- Validate form for submit button ----
  useEffect(() => {
    const ok =
      selectedLine &&
      selectedPart &&
      production &&
      parseInt(production) > 0 &&
      parseInt(production) <= 15000;
    setShowSubmitButton(ok);
  }, [selectedLine, selectedPart, production]);

  // Frame paths for animations
  const BASE_PATH = window.location.hostname === 'localhost' ? '' : process.env.PUBLIC_URL;
  const BOX_DIR = `${BASE_PATH}/assets/boxframes`;
  const CAR_DIR = `${BASE_PATH}/assets/carframes`;
  const BOX_FRAME_COUNT = 49;
  const CAR_FRAME_COUNT = 49;
  
  // Generate frame paths
  const boxFrames = Array.from({ length: BOX_FRAME_COUNT }, (_, i) => 
    `frame_${i.toString().padStart(3, '0')}.png`
  );
  // carFrames removed as it's not used in current implementation

  useEffect(() => {
    // preload Section 1 frames
    const preload1 = async () => {
      const promises = [];
      for (let i = 1; i <= BOX_FRAME_COUNT; i++) {
        const num = (i - 1).toString().padStart(3, '0');
        const imagePath = `${BOX_DIR}/frame_${num}.png`;
        const img = new Image();
        img.src = imagePath;
        promises.push(
          new Promise((res, rej) => {
            img.onload = res;
            img.onerror = () => rej(new Error(`Failed to load image: ${imagePath}`));
          })
        );
      }
      try { await Promise.all(promises); } catch (error) { 
        console.warn('Some box frames failed to load:', error);
      }
      setFrames1Loaded(true);
    };
    // preload Section 2 frames
    const preload2 = async () => {
      const promises = [];
      for (let i = 1; i <= CAR_FRAME_COUNT; i++) {
        const num = (i - 1).toString().padStart(3, '0');
        const imagePath = `${CAR_DIR}/frame_${num}.png`;
        const img = new Image();
        img.src = imagePath;
        promises.push(
          new Promise((res, rej) => {
            img.onload = res;
            img.onerror = () => rej(new Error(`Failed to load image: ${imagePath}`));
          })
        );
      }
      try { await Promise.all(promises); } catch (error) { 
        console.warn('Some car frames failed to load:', error);
      }
      setFrames2Loaded(true);
    };

    const loadAssets = async () => {
      await Promise.all([preload1(), preload2()]);
      // Refresh any layout calculations after assets load
      setTimeout(() => {
        window.dispatchEvent(new Event('resize'));
      }, 100);
    };
    
    loadAssets();
  }, [BOX_DIR, CAR_DIR]); // Dependencies for frame directories

  // ---- Submit handler: start Section 1 ----
  const handleSubmit = (e) => {
    e.preventDefault();
    // Ensure we start fresh
    setCurrentFrame1(0);
    setCurrentFrame2(0);
    // Reset animation states
    // Hide restart button if visible
    setShowRestartButton(false);
    // Start section 1
    setCurrentStep(1);
  };

  // ---- Computations for text displays ----
  const parsePrice = (s) => s ? parseFloat(s.replace(/[^0-9.]/g, '')) : 0;
  const parseWeight = (s) => s ? parseFloat(s.replace(/[^0-9.]/g, '')) : 0;

  const prodCount = parseInt(production || '0', 10) || 0;
  const cartonQty = selectedPartData ? parseInt(selectedPartData['Carton Qty'], 10) || 1 : 1;
  const unitWeight = selectedPartData ? parseWeight(selectedPartData['Unit Weight (lb)']) : 0;
  const unitPrice = selectedPartData ? parsePrice(selectedPartData['Price (ea)']) : 0;

  const totalBoxes = cartonQty ? Math.ceil(prodCount / cartonQty) : 0;
  const totalWeightLbs = unitWeight * prodCount;
  const retailValue = unitPrice * prodCount;

  // Cars equivalent (Section 2)
  const SMALL_CAR_LBS = 2800;
  const carEquivalent = totalWeightLbs > 0 ? (totalWeightLbs / SMALL_CAR_LBS) : 0;

  // Section 4: Production value breakdown calculations
  const wageRate = 21; // $21/hour
  const wage = wageRate * 8; // 8 hour shift
  const steelPricePerLb = 0.54; // July 2024 galvanized steel coil price
  const screwCostPerPart = 0.10; // $0.10 screws per part
  const steelCost = (unitWeight * prodCount * steelPricePerLb) + (prodCount * screwCostPerPart);
  const overhead = retailValue * 0.35; // 35% of retail value
  const companyMargin = Math.max(0, retailValue - (wage + steelCost + overhead));

  // ---- Section 1: Auto-play frame animation ----
  useEffect(() => {
    if (currentStep !== 1 || !frames1Loaded) return;

    // Animation state managed by individual section effects
    setCurrentFrame1(0);

    // Animate through frames 0 to 48
    const tl = gsap.timeline({
      onComplete: () => {
        // Reset animation states
        // Auto-advance to next section after brief pause
        setTimeout(() => {
          setCurrentStep(2);
        }, 500);
      }
    });

    tl.to({}, {
      duration: 3,
      ease: 'none',
      onUpdate: function() {
        const progress = this.progress();
        const frameIndex = Math.floor(progress * (BOX_FRAME_COUNT - 1));
        setCurrentFrame1(frameIndex);
      }
    });

    return () => tl.kill();
  }, [currentStep, frames1Loaded]);

  // ---- Section 2: Auto-play frame animation ----
  useEffect(() => {
    if (currentStep !== 2 || !frames2Loaded) return;

    // Animation state managed by individual section effects
    setCurrentFrame2(0);

    // Animate through frames 0 to 48
    const tl = gsap.timeline({
      onComplete: () => {
        // Reset animation states
        // Auto-advance to next section after brief pause
        setTimeout(() => {
          setCurrentStep(3);
        }, 500);
      }
    });

    tl.to({}, {
      duration: 3,
      ease: 'none',
      onUpdate: function() {
        const progress = this.progress();
        const frameIndex = Math.floor(progress * (CAR_FRAME_COUNT - 1));
        setCurrentFrame2(frameIndex);
      }
    });

    return () => tl.kill();
  }, [currentStep, frames2Loaded]);

  // ---- Section 3: Auto-play Lottie animation ----
  useEffect(() => {
    if (currentStep !== 3 || !section3Ref.current) return;

    let anim;
    let cancelled = false;

    // Animation state managed by individual section effects

    (async () => {
      try {
        // Load JSON from public/assets to be GH Pages friendly
        const jsonPath = `${BASE_PATH}/assets/cashrain.json`;
        const response = await fetch(jsonPath);
        const data = await response.json();
        if (cancelled) return;

        const container = section3Ref.current.querySelector('.lottie-container');
        if (!container) return;

        anim = lottie.loadAnimation({
          container,
          renderer: 'svg',
          loop: false,
          autoplay: true,
          animationData: data
        });

        anim.addEventListener('complete', () => {
          // Reset animation states
          // Auto-advance to next section after brief pause
          setTimeout(() => {
            setCurrentStep(4);
          }, 500);
        });

      } catch (e) {
        // If loading fails, still advance after delay
        console.error('Lottie load error:', e);
        if (!cancelled) {
          setTimeout(() => {
            // Animation complete
            // Auto-advance to next section after brief pause
            setTimeout(() => {
              if (!cancelled) {
                setCurrentStep(4);
              }
            }, 500);
          }, 2000);
        }
      }
    })();

    return () => {
      cancelled = true;
      if (anim) anim.destroy();
    };
  }, [currentStep, BASE_PATH]);

  // ---- Section 4: Auto-play bar chart animation ----
  useEffect(() => {
    if (currentStep !== 4) return;

    // Animation state managed by individual section effects

    // Reset animated values
    setAnimatedWage(0);
    setAnimatedSteel(0);
    setAnimatedOverhead(0);
    setAnimatedMargin(0);

    // Create stacked bar chart - single bar with segments
    const totalHeight = 300; // Fixed height for the stacked bar
    
    // Heights are calculated in the render function, not needed here

    // Animate stacked segments growing up together
    const tl = gsap.timeline({
      onComplete: () => {
        // Reset animation states
        // Show restart button after animation completes
        setTimeout(() => {
          setShowRestartButton(true);
        }, 500);
      }
    });

    // Animate wage segment (bottom)
    tl.to({}, {
      duration: 1.2,
      ease: 'power2.out',
      onUpdate: function() {
        const progress = this.progress();
        setAnimatedWage(Math.round(wage * progress));
      }
    }, 0)
    // Animate steel segment
    .to({}, {
      duration: 1.4,
      ease: 'power2.out',
      onUpdate: function() {
        const progress = this.progress();
        setAnimatedSteel(Math.round(steelCost * progress));
      }
    }, 0.2)
    // Animate overhead segment
    .to({}, {
      duration: 1.6,
      ease: 'power2.out',
      onUpdate: function() {
        const progress = this.progress();
        setAnimatedOverhead(Math.round(overhead * progress));
      }
    }, 0.4)
    // Animate margin segment (top)
    .to({}, {
      duration: 1.8,
      ease: 'power2.out',
      onUpdate: function() {
        const progress = this.progress();
        setAnimatedMargin(Math.round(companyMargin * progress));
      }
    }, 0.6);

    return () => tl.kill();
  }, [currentStep, wage, steelCost, overhead, companyMargin]);

  // ---- Navigation functions ----
  const handleRestart = () => {
    setCurrentStep(0);
    // Reset animation states
    setCurrentFrame1(0);
    setCurrentFrame2(0);
    setShowRestartButton(false);
    // Reset animated values
    setAnimatedWage(0);
    setAnimatedSteel(0);
    setAnimatedOverhead(0);
    setAnimatedMargin(0);
  };

  // ---- Render ----
  return (
    <div className="min-h-screen" style={{ backgroundColor: 'rgba(242,238,235,1)' }}>
      {/* Form - Only show when currentStep is 0 */}
      {currentStep === 0 && (
        <>
          {/* Header - Only show on first section */}
          <div className="shadow-sm" style={{ backgroundColor: 'rgba(242,238,235,1)' }}>
            <div className="max-w-md mx-auto px-4 py-8">
              <h1 className="text-3xl font-bold text-gray-900 text-center mb-4">
                Workload Stats
              </h1>
              <p className="text-gray-600 text-center text-sm leading-relaxed">
                Track your daily production and see the real impact of your work.
              </p>
            </div>
          </div>
          <div className="max-w-md mx-auto px-4 py-8">
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Line */}
            <div>
              <label htmlFor="line" className="block text-sm font-medium text-gray-700 mb-2">
                Select Line
              </label>
              <select
                id="line"
                value={selectedLine}
                onChange={(e) => setSelectedLine(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
              >
                <option value="">Choose a line...</option>
                {lines.map(line => (
                  <option key={line} value={line}>{line}</option>
                ))}
              </select>
            </div>

            {/* Part */}
            {selectedLine && (
              <div>
                <label htmlFor="part" className="block text-sm font-medium text-gray-700 mb-2">
                  Select Part
                </label>
                <select
                  id="part"
                  value={selectedPart}
                  onChange={(e) => setSelectedPart(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                >
                  <option value="">Choose a part...</option>
                  {availableParts.map(part => (
                    <option key={part.SKU} value={part.SKU}>
                      TP{part.SKU}
                    </option>
                  ))}
                </select>
              </div>
            )}

            {/* Production */}
            {selectedPart && (
              <div>
                <label htmlFor="production" className="block text-sm font-medium text-gray-700 mb-2">
                  Production Count
                </label>
                <input
                  type="number"
                  id="production"
                  value={production}
                  onChange={(e) => setProduction(e.target.value)}
                  min="1"
                  max="15000"
                  placeholder="Enter production count"
                  className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                />
              </div>
            )}

            {/* Submit */}
            {showSubmitButton && (
              <button
                type="submit"
                className="w-full bg-blue-600 text-white py-3 px-4 rounded-md font-medium hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 transition-colors"
              >
                Calculate My Stats
              </button>
            )}
          </form>
          </div>
        </>
      )}

      {/* Section 1: Boxes Stacked */}
      {currentStep === 1 && (
        <div
          ref={section1Ref} className="h-screen w-full flex items-center justify-center relative overflow-hidden"
          style={{ backgroundColor: 'rgba(242,238,235,1)' }}
        >
          {/* PixiCanvas */}
          <div className="absolute inset-0 z-0">
            <PixiCanvas 
              width={window.innerWidth} 
              height={window.innerHeight}
              frames={boxFrames}
              frameDir={BOX_DIR}
              frameIndex={currentFrame1}
            />
          </div>

          {/* Gradient scrim */}
          <div className="absolute inset-0 bg-gradient-to-b from-black/35 via-transparent to-black/20 pointer-events-none z-0" />

          {/* Text */}
          <div className="relative z-10">
            <div className="inline-block px-3 py-2 rounded-xl bg-black/40 backdrop-blur-sm">
              <h2 className="text-white font-bold tracking-tight text-4xl md:text-6xl" style={{ WebkitTextStroke: '1px rgba(0,0,0,0.55)' }}>
                You stacked {totalBoxes} boxes.
              </h2>
            </div>
          </div>

        </div>
      )}

      {/* Section 2: Weight Comparison */}
      {currentStep === 2 && (
        <div
          ref={section2Ref}
          className="h-screen w-full flex items-center justify-center relative overflow-hidden"
          style={{ backgroundColor: 'rgba(242,238,235,1)' }}
        >
          {/* Frame image */}
          {frames2Loaded && (
            <img
              src={`${CAR_DIR}/frame_${currentFrame2.toString().padStart(3, '0')}.png`}
              alt={`Frame ${currentFrame2 + 1}`}
              className="absolute inset-0 m-auto max-w-full max-h-full object-contain z-0"
            />
          )}

          {/* Gradient scrim */}
          <div className="absolute inset-0 bg-gradient-to-b from-black/35 via-transparent to-black/20 pointer-events-none z-0" />

          {/* Text */}
          <div className="text-center px-4 relative z-10">
            <div className="inline-block px-3 py-2 rounded-xl bg-black/40 backdrop-blur-sm">
              <h2 className="text-white font-bold tracking-tight text-4xl md:text-6xl" style={{ WebkitTextStroke: '1px rgba(0,0,0,0.55)' }}>
                That equals {Math.round(totalWeightLbs).toLocaleString()} lbs
              </h2>
              <p className="text-emerald-100 text-lg mt-2">
                (like lifting {carEquivalent.toFixed(1)} small cars)
              </p>
            </div>
          </div>

        </div>
      )}

      {/* Section 3: Retail Value */}
      {currentStep === 3 && (
        <div
          ref={section3Ref}
          className="h-screen w-full flex items-center justify-center relative overflow-hidden"
          style={{ backgroundColor: 'rgba(242,238,235,1)' }}
        >
          {/* Lottie container */}
          <div className="absolute inset-0 lottie-container pointer-events-none z-0" />

          {/* Gradient scrim */}
          <div className="absolute inset-0 bg-gradient-to-b from-black/35 via-transparent to-black/20 pointer-events-none z-0" />

          {/* Text */}
          <div className="text-center px-4 relative z-10">
            <div className="inline-block px-3 py-2 rounded-xl bg-black/40 backdrop-blur-sm">
              <h2 className="text-white font-bold tracking-tight text-4xl md:text-6xl" style={{ WebkitTextStroke: '1px rgba(0,0,0,0.55)' }}>
                Retail value: ${Math.round(retailValue).toLocaleString()}
              </h2>
              <p className="text-white/90 text-lg mt-2">
                That's the value you helped create.
              </p>
            </div>
          </div>

        </div>
      )}

      {/* Section 4: Wage vs Retail */}
      {currentStep === 4 && (
        <div
          ref={section4Ref}
          className="h-screen w-full flex flex-col items-center justify-center relative overflow-hidden"
          style={{ backgroundColor: 'rgba(242,238,235,1)' }}
        >
          {/* Gradient scrim */}
          <div className="absolute inset-0 bg-gradient-to-b from-black/35 via-transparent to-black/20 pointer-events-none z-0" />

          <div className="relative z-10">
            <div className="inline-block px-3 py-2 rounded-xl bg-black/40 backdrop-blur-sm mb-8">
              <h2 className="text-white font-bold tracking-tight text-4xl md:text-6xl" style={{ WebkitTextStroke: '1px rgba(0,0,0,0.55)' }}>
                Production Value Breakdown
              </h2>
            </div>
          </div>

          {/* Value Summary Text */}
          <div className="relative z-10 mb-8">
            <div className="inline-block px-4 py-3 rounded-xl bg-black/40 backdrop-blur-sm">
              <div className="grid grid-cols-2 gap-4 text-white text-sm md:text-base">
                <div>Your estimated wage: <span className="font-bold text-blue-300">${Math.round(wage).toLocaleString()}</span></div>
                <div>Estimated steel cost: <span className="font-bold text-gray-300">${Math.round(steelCost).toLocaleString()}</span></div>
                <div>Retail value: <span className="font-bold text-green-300">${Math.round(retailValue).toLocaleString()}</span></div>
                <div>Overhead (approx. e.g. management salaries): <span className="font-bold text-purple-300">${Math.round(overhead).toLocaleString()}</span></div>
                <div className="col-span-2">Company margin: <span className="font-bold text-orange-300">${Math.round(companyMargin).toLocaleString()}</span></div>
              </div>
            </div>
          </div>

          {/* Stacked Bar Chart */}
          <div className="flex items-center justify-center h-[50%] w-[90%] max-w-2xl relative z-10">
            <div className="flex flex-col items-center">
              <div className="relative w-32 h-80 border-2 border-gray-400 rounded-lg overflow-hidden bg-white/10 flex flex-col-reverse">
                {(() => {
                  const totalValue = wage + steelCost + overhead + companyMargin;
                  const totalHeight = 300;
                  const wageHeight = totalValue > 0 ? (animatedWage / totalValue) * totalHeight : 0;
                  const steelHeight = totalValue > 0 ? (animatedSteel / totalValue) * totalHeight : 0;
                  const overheadHeight = totalValue > 0 ? (animatedOverhead / totalValue) * totalHeight : 0;
                  const marginHeight = totalValue > 0 ? (animatedMargin / totalValue) * totalHeight : 0;
                  
                  return (
                    <>
                      {/* Wage segment (bottom) */}
                      <div className="w-full bg-blue-500 flex items-center justify-center transition-all duration-300" style={{ height: `${wageHeight}px` }}>
                        <span className="text-white text-xs font-bold">${animatedWage.toLocaleString()}</span>
                      </div>
                      {/* Steel segment */}
                      <div className="w-full bg-gray-500 flex items-center justify-center transition-all duration-300" style={{ height: `${steelHeight}px` }}>
                        <span className="text-white text-xs font-bold">${animatedSteel.toLocaleString()}</span>
                      </div>
                      {/* Overhead segment */}
                      <div className="w-full bg-purple-500 flex items-center justify-center transition-all duration-300" style={{ height: `${overheadHeight}px` }}>
                        <span className="text-white text-xs font-bold">${animatedOverhead.toLocaleString()}</span>
                      </div>
                      {/* Margin segment (top) */}
                      <div className="w-full bg-orange-500 flex items-center justify-center transition-all duration-300" style={{ height: `${marginHeight}px` }}>
                        <span className="text-white text-xs font-bold">${animatedMargin.toLocaleString()}</span>
                      </div>
                    </>
                  );
                })()}
              </div>
              
              {/* Labels */}
              <div className="mt-4 text-center">
                <div className="grid grid-cols-2 gap-2 text-xs">
                  <div className="flex items-center"><div className="w-3 h-3 bg-blue-500 rounded mr-1"></div>Your Wage</div>
                  <div className="flex items-center"><div className="w-3 h-3 bg-gray-500 rounded mr-1"></div>Steel Cost</div>
                  <div className="flex items-center"><div className="w-3 h-3 bg-purple-500 rounded mr-1"></div>Overhead (approx.)</div>
                  <div className="flex items-center"><div className="w-3 h-3 bg-orange-500 rounded mr-1"></div>Company Margin</div>
                </div>
              </div>
            </div>
          </div>

          {/* Restart Button */}
          {showRestartButton && (
            <div className="absolute bottom-8 left-1/2 transform -translate-x-1/2 z-20 animate-fade-in">
              <button
                onClick={handleRestart}
                className="bg-green-600 text-white px-8 py-3 rounded-lg font-medium hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 transition-colors shadow-lg"
              >
                ↻ Restart
              </button>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default App;
